import{_ as a,o as e,c as t,ao as i}from"./chunks/framework.CKOtou8s.js";const k=JSON.parse('{"title":"2D VFSA inversion","description":"","frontmatter":{},"headers":[],"relativePath":"inversion/2d_vfsa.md","filePath":"inversion/2d_vfsa.md","lastUpdated":null}'),n={name:"inversion/2d_vfsa.md"};function l(h,s,o,r,p,d){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="2D-VFSA-inversion" tabindex="-1">2D VFSA inversion <a class="header-anchor" href="#2D-VFSA-inversion" aria-label="Permalink to &quot;2D VFSA inversion {#2D-VFSA-inversion}&quot;">​</a></h1><p>Very fast simulated annealing (VFSA) is a global search. Instead of following the gradient downhill, it tries random changes to the model. A change that improves the fit is kept. A change that makes the fit worse is sometimes kept too, so the search can climb out of a poor local solution. As the run goes on, the &quot;temperature&quot; drops: the changes become smaller and bad changes are accepted less often.</p><p>Because each run is random, we run several independent chains. Their best models form an <strong>ensemble</strong>, and the spread of the ensemble shows how well each part of the model is resolved.</p><p>To keep the search small, VFSA does not change every cell. It moves a few hundred control points, and the model between them follows smoothly (Gaussian radial basis functions).</p><h2 id="What-you-need" tabindex="-1">What you need <a class="header-anchor" href="#What-you-need" aria-label="Permalink to &quot;What you need {#What-you-need}&quot;">​</a></h2><p>VFSA reads five files. There is no covariance and no prior model, because VFSA has no regularisation: the start model is the centre of the search, and the mask says which cells may change.</p><table tabindex="0"><thead><tr><th style="text-align:left;">File</th><th style="text-align:left;">Contents</th></tr></thead><tbody><tr><td style="text-align:left;"><code>model.start</code></td><td style="text-align:left;">the model to start from</td></tr><tr><td style="text-align:left;"><code>data.dat</code></td><td style="text-align:left;">the observed data</td></tr><tr><td style="text-align:left;"><code>fwd.ctrl</code></td><td style="text-align:left;">mode, strike and air (see <a href="./../forward/2d">2D forward</a>)</td></tr><tr><td style="text-align:left;"><code>vfsa.ctrl</code></td><td style="text-align:left;">the VFSA settings</td></tr><tr><td style="text-align:left;"><code>mask.ctrl</code></td><td style="text-align:left;">which cells are free, fixed, air or water (see <a href="./../data/mesh2d">Masks</a>)</td></tr></tbody></table><p>The <a href="./../data/mesh2d">2D mesh tool</a> writes all five.</p><h2 id="Run-the-example" tabindex="-1">Run the example <a class="header-anchor" href="#Run-the-example" aria-label="Permalink to &quot;Run the example {#Run-the-example}&quot;">​</a></h2><p>Each chain runs on its own Julia thread, so start Julia with as many threads as chains (<code>-t</code>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_vfsa2D.jl</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # examples/data/2D-IV</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 10</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/run_vfsa2D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> model.start</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> data.dat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FwdCtrl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> InvCtrl.VFSA</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mask.ctrl</span></span></code></pre></div><h2 id="The-VFSA-control-file" tabindex="-1">The VFSA control file <a class="header-anchor" href="#The-VFSA-control-file" aria-label="Permalink to &quot;The VFSA control file {#The-VFSA-control-file}&quot;">​</a></h2><p>The example <code>examples/ctrl/2D/InvCtrl.VFSA</code> starts like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Exit search when rms is less than : 1</span></span>
<span class="line"><span>Maximum number of iterations      : 3000</span></span>
<span class="line"><span>Mode                              : TETM</span></span>
<span class="line"><span>Log10 resistivity bounds          : 0 4</span></span>
<span class="line"><span>Number of chains                  : 2</span></span>
<span class="line"><span>Control points                    : 400</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>The settings that matter most are:</p><ul><li><p><code>Maximum number of iterations</code>: iterations per chain. More iterations give a slower, more careful search.</p></li><li><p><code>Log10 resistivity bounds</code>: the range the search may explore, here 1 to 10 000 Ω·m.</p></li><li><p><code>Number of chains</code>: the size of the ensemble.</p></li><li><p><code>Control points</code>: how many points the search moves. More points allow more detail but make the search harder.</p></li></ul><p>The remaining keys (cooling, control-point widths, core depth, padding) have sensible defaults and are explained in the <a href="./../developers/control_files">control file reference</a>.</p><h2 id="From-Julia" tabindex="-1">From Julia <a class="header-anchor" href="#From-Julia" aria-label="Permalink to &quot;From Julia {#From-Julia}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MTGeophysics</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> VFSA2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;model.start&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;data.dat&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;FwdCtrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;InvCtrl.VFSA&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mask.ctrl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PlotInversion2D</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(run; true_model_path </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;model.true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="What-you-get" tabindex="-1">What you get <a class="header-anchor" href="#What-you-get" aria-label="Permalink to &quot;What you get {#What-you-get}&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>run_YYYYmmdd_HHMMSS/</span></span>
<span class="line"><span>├── model.rho        ensemble mean, the result of the run</span></span>
<span class="line"><span>├── data.pred        its predicted data</span></span>
<span class="line"><span>├── Summary.txt      rms of the mean and of each chain</span></span>
<span class="line"><span>├── inputs/          the five input files</span></span>
<span class="line"><span>├── plots/           mean, median, best, 5 % and 95 % models, standard deviation, data fit, convergence</span></span>
<span class="line"><span>└── vfsa/            each chain&#39;s best model and history, and the ensemble statistics</span></span></code></pre></div><p>The standard deviation and the 5–95 % models are the ones to look at for uncertainty. Where they are wide, the data do not constrain the model well.</p><p>To recompute the ensemble statistics from the chains later, for example after removing a chain:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> helpers/run_statistics_2D.jl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run_dir</span></span></code></pre></div>`,24)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
